//! Reference outputs for the pure-Roc SipHash-1-3 and rapidhash v3.
//!
//! Messages are generated by `message(len)` on both sides, so only lengths and
//! hashes are written out.

pub mod layout;

use std::fmt::Write;
use std::hash::Hasher;

use rapidhash::v3::{rapidhash_v3_seeded, RapidSecrets};
use siphasher::sip::SipHasher13;

/// The SipHash reference key: bytes 00..0f, read little-endian.
const SIP_K0: u64 = 0x0706_0504_0302_0100;
const SIP_K1: u64 = 0x0f0e_0d0c_0b0a_0908;

/// Seeds for rapidhash, through the C++-compatible `seed_cpp` secrets.
const RAPID_SEEDS: [u64; 2] = [0, 0x0123_4567_89ab_cdef];

/// Every length up to 64 (the SipHash paper's range), then the boundaries
/// rapidhash branches on (4, 8, 16, 112, 224) and a few long inputs.
fn lengths() -> Vec<usize> {
    let mut lens: Vec<usize> = (0..=64).collect();
    lens.extend([79, 80, 81, 95, 96, 97, 111, 112, 113, 127, 128, 129, 223, 224, 225, 336, 337, 1000]);
    lens
}

/// Mirrors `HashVectors.message` in Roc.
pub fn message(len: usize) -> Vec<u8> {
    (0..len).map(|i| ((i * 7 + 3) % 256) as u8).collect()
}

fn sip13(bytes: &[u8]) -> u64 {
    let mut hasher = SipHasher13::new_with_keys(SIP_K0, SIP_K1);
    hasher.write(bytes);
    hasher.finish()
}

fn rapid(bytes: &[u8], seed: u64) -> u64 {
    rapidhash_v3_seeded(bytes, &RapidSecrets::seed_cpp(seed))
}

pub fn render() -> String {
    let mut out = String::new();
    out.push_str("## Generated by tests/vectors (`cargo run`); do not edit.\n");
    out.push_str("## Reference outputs from the Rust crates siphasher 1.0.3 (SipHasher13)\n");
    out.push_str("## and rapidhash 4.5.1 (v3, `RapidSecrets::seed_cpp`).\n");
    out.push_str("HashVectors :: [].{\n");
    out.push_str("\t## The message of length `len` every vector hashes.\n");
    out.push_str("\tmessage : U64 -> List(U8)\n");
    out.push_str("\tmessage = |len| List.repeat(0, len).map_with_index(|_, i| U64.to_u8_wrap((i * 7 + 3) % 256))\n\n");
    out.push_str("\tsip_key : { k0 : U64, k1 : U64 }\n");
    writeln!(out, "\tsip_key = {{ k0: {SIP_K0:#x}, k1: {SIP_K1:#x} }}\n").unwrap();
    out.push_str("\tsip13 : List({ len : U64, hash : U64 })\n");
    out.push_str("\tsip13 = [\n");
    for len in lengths() {
        writeln!(out, "\t\t{{ len: {len}, hash: {:#018x} }},", sip13(&message(len))).unwrap();
    }
    out.push_str("\t]\n\n");
    out.push_str("\trapid : List({ seed : U64, len : U64, hash : U64 })\n");
    out.push_str("\trapid = [\n");
    for seed in RAPID_SEEDS {
        for len in lengths() {
            writeln!(out, "\t\t{{ seed: {seed:#x}, len: {len}, hash: {:#018x} }},", rapid(&message(len), seed)).unwrap();
        }
    }
    out.push_str("\t]\n");
    out.push_str("}\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn committed_layout_matches_the_documented_table() {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../layout/expected");
        let committed = std::fs::read_to_string(path).expect("tests/layout/expected exists; run `cargo run` in tests/vectors");
        assert_eq!(committed, layout::expected(), "tests/layout/expected is stale; run `cargo run` in tests/vectors");
    }

    #[test]
    fn committed_vectors_match_the_reference_crates() {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../components/hash/HashVectors.roc");
        let committed = std::fs::read_to_string(path).expect("HashVectors.roc exists; run `cargo run` in tests/vectors");
        assert_eq!(committed, render(), "HashVectors.roc is stale; run `cargo run` in tests/vectors");
    }

    /// The SipHash paper's first 2-4 vector would not apply to 1-3; this pins
    /// that the key and message conventions are the reference ones by checking
    /// SipHash-2-4 on the same inputs against the paper's value for len 0.
    #[test]
    fn key_and_message_conventions_match_the_siphash_paper() {
        let mut hasher = siphasher::sip::SipHasher24::new_with_keys(SIP_K0, SIP_K1);
        hasher.write(&[]);
        assert_eq!(hasher.finish(), 0x726f_db47_dd0e_0e31);
    }
}
